/* eslint-disable */
import { list_supplier_transaction } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import PurchasePaymentSuplier from "./PurchasePaymentSuplier.vue";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import SuplierTransactionView from "./SuplierTransactionView.vue";
export default {
  props: {
    SuplierDetails: Boolean,
    SuplierData: Object
  },
  components: {
    PurchasePaymentSuplier,
    SuplierTransactionView
  },
  data() {
    return {
      suplierLoading: false,
      supplierHeight: 0,
      contenHeight: 0,
      SupliersData: [],
      suplierHeaders: [{
        text: "Pending Amount",
        value: "pending_amount",
        sortable: false
      }, {
        text: "Amount Paid",
        value: "amount_paid",
        sortable: false
      }, {
        text: "Transaction Type",
        value: "transaction_type",
        sortable: false
      }],
      searchlist: "",
      fixed: true,
      cardValue: 1,
      getbalance: 0,
      purchase_payment_Type: "",
      itemValue: {}
    };
  },
  watch: {
    SuplierDetails: {
      async handler(newValue) {
        if (newValue === true) {
          await this.getSupliers();
        }
      },
      immediate: true
    }
  },
  mounted() {
    this.supplierHeight = window.innerHeight - 130;
    this.contenHeight = window.innerHeight - 300;
  },
  computed: {
    balanceText() {
      if (this.getbalance === 0) {
        return `₹ 0`;
      }
      return this.getbalance < 0 ? `You will get: ₹ ${Math.abs(this.getbalance)}` : `You will give: ₹ ${this.getbalance}`;
    },
    balanceColor() {
      if (this.getbalance === 0) {
        return "black";
      }
      return this.getbalance < 0 ? "red" : "green";
    },
    iconName() {
      if (this.getbalance === 0) {
        return "";
      }
      return this.getbalance < 0 ? "mdi-arrow-bottom-left" : "mdi-arrow-top-right";
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    formatTimestamp(unixTimestamp) {
      if (!unixTimestamp) return "";
      const date = new Date(unixTimestamp * 1000);
      return date.toLocaleString("en-US", {
        hour: "numeric",
        minute: "numeric",
        hour12: true
      });
    },
    get_updatedate(date) {
      if (date != "" && date != undefined) {
        return formatdisplayDate(date);
      }
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.SupliersData = [];
      this.cardValue = 1;
      this.getSupliers();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    purchase_payment_Tab(item) {
      this.purchase_payment_Type = item;
      this.cardValue = 2;
      this.itemValue = this.SuplierData;
    },
    async getSupliers() {
      this.suplierLoading = true;
      this.SupliersData = [];
      try {
        let result = await API.graphql(graphqlOperation(list_supplier_transaction, {
          input: {
            suppliers_id: this.SuplierData.supplier.suppliers_id
          }
        }));
        var response = JSON.parse(result.data.list_supplier_transaction);
        this.suplierLoading = false;
        if (response.Status === "SUCCESS") {
          this.SupliersData = response.data.transactions.sort((a, b) => b.transaction_timestamp - a.transaction_timestamp);
          this.getbalance = response.data.summary.balanceDue == undefined ? 0 : response.data.summary.balanceDue;
          connsole.log(this.getbalance, " this.getbalance");
          this.suplierLoading = false;
        } else {
          this.SupliersData = [];
          this.suplierLoading = false;
        }
      } catch (error) {
        this.suplierLoading = false;
        // console.error("API error:", error);
      }
    },
    backAction() {
      this.cardValue = 1;
      this.getSupliers();
    },
    View_Details(item) {
      this.TransactionDetails = item;
      this.cardValue = 3;
      this.itemValue = this.SuplierData;
    }
  }
};
